import { Client } from 'pg';
import { readFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
// The SQL is generated by Prisma; this small runner avoids Prisma 6's experimental
// JS migration engine's unsupported PostgreSQL `name` type. Never mix ledgers.
const client = new Client({ connectionString: process.env.DATABASE_URL });
await client.connect();
try {
  await client.query('SELECT pg_advisory_lock(2147483646)');
  await client.query(
    'CREATE TABLE IF NOT EXISTS convyn_schema_migrations (name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now())',
  );
  const directory = new URL('../prisma/migrations/', import.meta.url);
  const files = (await readdir(directory, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();
  const applied = (
    await client.query('SELECT name,checksum FROM convyn_schema_migrations')
  ).rows;
  for (const entry of applied)
    if (!files.includes(entry.name))
      throw new Error('Previously applied migration is missing: ' + entry.name);
  for (const name of files) {
    const sql = await readFile(
      new URL(name + '/migration.sql', directory),
      'utf8',
    );
    const checksum = createHash('sha256').update(sql).digest('hex');
    const previous = applied.find((entry) => entry.name === name);
    if (previous) {
      if (previous.checksum !== checksum)
        throw new Error('Applied migration checksum changed: ' + name);
      continue;
    }
    await client.query('BEGIN');
    try {
      await client.query(sql);
      await client.query(
        'INSERT INTO convyn_schema_migrations(name,checksum) VALUES ($1,$2)',
        [name, checksum],
      );
      await client.query('COMMIT');
      console.log('Applied migration: ' + name);
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    }
  }
  console.log('Database migrations are current');
} finally {
  await client.end();
}
